import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './auth/AuthContext';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import ProtectedRoute from './components/ProtectedRoute';
import RequireRole from './components/RequireRole';

import Home from './pages/Home';
import Cars from './pages/Cars';
import CarDetail from './pages/CarDetail';
import Login from './pages/Login';
import Register from './pages/Register';
import MyBookings from './pages/MyBookings';
import Profile from './pages/Profile';
import NotFound from './pages/NotFound';

import AdminLayout from './pages/admin/AdminLayout';
import AdminDashboard from './pages/admin/AdminDashboard';
import AdminCars from './pages/admin/AdminCars';
import AdminCarForm from './pages/admin/AdminCarForm';
import AdminBookings from './pages/admin/AdminBookings';

export default function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <div className="min-h-screen flex flex-col bg-[#f5f6f8]">
          <Navbar />
          <main className="flex-1">
            <Routes>
              {/* หน้าแรกกางเต็มจอเพื่อให้แถบสีดำชิดขอบ */}
              <Route path="/" element={<Home />} />

              {/* หน้าอื่นๆ จัดกึ่งกลาง */}
              <Route path="/cars" element={<div className="max-w-5xl mx-auto px-6 py-8"><Cars /></div>} />
              <Route path="/cars/:id" element={<div className="max-w-5xl mx-auto px-6 py-8"><CarDetail /></div>} />
              <Route path="/login" element={<div className="max-w-5xl mx-auto px-6 py-12"><Login /></div>} />
              <Route path="/register" element={<div className="max-w-5xl mx-auto px-6 py-12"><Register /></div>} />

              <Route path="/my-bookings" element={<ProtectedRoute><div className="max-w-5xl mx-auto px-6 py-8"><MyBookings /></div></ProtectedRoute>} />
              <Route path="/profile" element={<ProtectedRoute><div className="max-w-5xl mx-auto px-6 py-8"><Profile /></div></ProtectedRoute>} />

              <Route path="/admin" element={<RequireRole role="admin"><div className="max-w-6xl mx-auto px-6 py-8"><AdminLayout /></div></RequireRole>}>
                <Route index element={<AdminDashboard />} />
                <Route path="cars" element={<AdminCars />} />
                <Route path="cars/new" element={<AdminCarForm />} />
                <Route path="cars/edit/:id" element={<AdminCarForm />} />
                <Route path="bookings" element={<AdminBookings />} />
              </Route>

              <Route path="*" element={<NotFound />} />
            </Routes>
          </main>
          <Footer />
        </div>
      </BrowserRouter>
    </AuthProvider>
  );
}
